// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz params: address fromAddr (fuzzable actor), uint256 v (value), uint256 nTos (number of tos)
    function testFuzz_property(address fromAddr, uint256 v, uint256 nTos) public {
        // keep domain sensible but wide
        vm.assume(fromAddr != address(0));
        uint256 tosCount = bound(nTos, 1, 5); // ensure at least one recipient to satisfy require(_tos.length > 0)

        // Deploy a helper that can be switched to either succeed or revert on the call.
        RecorderOrReverter helper = new RecorderOrReverter();

        // Build tos array with the helper's address repeated tosCount times so every call targets our helper
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) tos[i] = address(helper);

        // Case A: helper is set to succeed. For the reference contract, transfer should return true.
        helper.setShouldRevert(false);
        bool okA;
        try c.transfer(fromAddr, address(helper), tos, v) {
            okA = true;
        } catch {
            okA = false;
        }

        // Case B: helper is set to revert on each call. For the reference contract, transfer should still return true
        // because it ignores the return value of low-level call; for the mutant it will revert and okB will be false.
        helper.setShouldRevert(true);
        bool okB;
        try c.transfer(fromAddr, address(helper), tos, v) {
            okB = true;
        } catch {
            okB = false;
        }

        // General rule we assert: reference C always returns true (both success and failing callee) -> okA && okB must be true.
        // This will pass on the reference C for all inputs, but the mutant (which reverts on external call failure)
        // will make okB == false for some inputs (when helper reverts), causing this assertion to fail.
        assertTrue(okA && okB);
    }
}

// Helper that either records calls or reverts based on a toggle. It exposes the exact target function signature
// transferFrom(address,address,uint256) so that abi.decode on the callee side properly works when C performs
// abi.encodeWithSelector(..., from, to, v).
contract RecorderOrReverter {
    bool public shouldRevert;
    // record number of calls received
    uint256 public calls;
    // latest decoded args
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // allow test to switch behaviour
    function setShouldRevert(bool r) external {
        shouldRevert = r;
    }

    // The function selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // matches this function signature so calls from C are ABI decoded and recorded.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        if (shouldRevert) revert("reverting as requested");
        return true;
    }

    // fallback to be safe if C calls via low-level selector differently
    fallback() external {
        if (shouldRevert) revert("reverting fallback");
        calls += 1;
    }
}
